import{_ as e,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"推理与采样","description":"理解前向计算、logits、softmax、贪心与随机采样、temperature、top-p、停止条件、KV cache 和延迟构成。","frontmatter":{"title":"推理与采样","description":"理解前向计算、logits、softmax、贪心与随机采样、temperature、top-p、停止条件、KV cache 和延迟构成。","verified_at":"2026-07-28","sources":["https://huggingface.co/docs/transformers/main/en/generation_strategies","https://huggingface.co/docs/transformers/main/en/llm_tutorial_optimization","https://arxiv.org/abs/2005.14165"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/inference-sampling.md","filePath":"py-agent/foundations/model-principles/inference-sampling.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/inference-sampling.md"};function l(n,a,h,s,d,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="推理与采样" tabindex="-1">推理与采样 <a class="header-anchor" href="#推理与采样" aria-label="Permalink to &quot;推理与采样&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>训练更新参数，推理则固定参数并用它们处理一次请求。自回归推理先计算输入上下文，再逐步得到下一个 Token 的 logits；解码策略把 logits 转成实际选择，直到满足停止条件。理解这条链，才能正确解释随机性、输出长度和延迟。</p><h2 id="_1-推理阶段" tabindex="-1">1. 推理阶段 <a class="header-anchor" href="#_1-推理阶段" aria-label="Permalink to &quot;1. 推理阶段&quot;">​</a></h2><h3 id="_1-1-参数保持不变" tabindex="-1">1.1 参数保持不变 <a class="header-anchor" href="#_1-1-参数保持不变" aria-label="Permalink to &quot;1.1 参数保持不变&quot;">​</a></h3><p>普通模型调用不会执行反向传播或优化器更新。输入只影响本次前向计算产生的隐藏状态和输出分布，不会永久写入模型参数。</p><h3 id="_1-2-推理分为预填充与解码" tabindex="-1">1.2 推理分为预填充与解码 <a class="header-anchor" href="#_1-2-推理分为预填充与解码" aria-label="Permalink to &quot;1.2 推理分为预填充与解码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>输入状态</th><th>主要工作</th></tr></thead><tbody><tr><td>预填充（prefill）</td><td>整个已知输入</td><td>并行计算输入位置的隐藏状态与 KV cache</td></tr><tr><td>解码（decode）</td><td>每次新增一个 Token</td><td>利用历史 cache 预测下一个 Token</td></tr></tbody></table><p>长输入主要增加预填充工作，长输出主要增加逐步解码次数。二者对延迟的影响方式不同。</p><h3 id="_1-3-前向计算得到-logits" tabindex="-1">1.3 前向计算得到 logits <a class="header-anchor" href="#_1-3-前向计算得到-logits" aria-label="Permalink to &quot;1.3 前向计算得到 logits&quot;">​</a></h3><p>模型最后把目标位置的隐藏状态投影到词表维度，得到每个候选 Token 的 logit。logit 是未归一化分数，可以是任意实数；它本身不是概率。</p><h2 id="_2-从-logits-到概率" tabindex="-1">2. 从 logits 到概率 <a class="header-anchor" href="#_2-从-logits-到概率" aria-label="Permalink to &quot;2. 从 logits 到概率&quot;">​</a></h2><h3 id="_2-1-softmax-归一化分数" tabindex="-1">2.1 softmax 归一化分数 <a class="header-anchor" href="#_2-1-softmax-归一化分数" aria-label="Permalink to &quot;2.1 softmax 归一化分数&quot;">​</a></h3><p>对候选 logits <code>zᵢ</code>，softmax 给出概率：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(i) = exp(zᵢ) / Σⱼ exp(zⱼ)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所有概率非负且总和为 1。logit 的绝对值不如候选之间的差值重要：共同加上同一个常数不会改变 softmax 分布。</p><h3 id="_2-2-模型分布还会被解码器处理" tabindex="-1">2.2 模型分布还会被解码器处理 <a class="header-anchor" href="#_2-2-模型分布还会被解码器处理" aria-label="Permalink to &quot;2.2 模型分布还会被解码器处理&quot;">​</a></h3><p>服务可能应用 temperature、top-p、重复控制、禁止 Token、语法约束等处理，再进行选择。因此“模型原始分布”和“实际采样分布”应概念分离。</p><h3 id="_2-3-概率仍不是事实置信度" tabindex="-1">2.3 概率仍不是事实置信度 <a class="header-anchor" href="#_2-3-概率仍不是事实置信度" aria-label="Permalink to &quot;2.3 概率仍不是事实置信度&quot;">​</a></h3><p>这里的概率是“下一个 Token 在当前生成条件下被模型偏好的程度”。它不等于整条陈述真实的概率，也不能直接跨位置相乘后当作业务置信分。</p><h2 id="_3-贪心与随机采样" tabindex="-1">3. 贪心与随机采样 <a class="header-anchor" href="#_3-贪心与随机采样" aria-label="Permalink to &quot;3. 贪心与随机采样&quot;">​</a></h2><h3 id="_3-1-贪心解码" tabindex="-1">3.1 贪心解码 <a class="header-anchor" href="#_3-1-贪心解码" aria-label="Permalink to &quot;3.1 贪心解码&quot;">​</a></h3><p>每一步都选择概率最高的 Token：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selected = argmax(probabilities)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>优点是简单、相对稳定；缺点是局部最优选择可能导致生硬、重复或错过更好的整段序列。每一步最优不保证整段文本全局最优。</p><h3 id="_3-2-随机采样" tabindex="-1">3.2 随机采样 <a class="header-anchor" href="#_3-2-随机采样" aria-label="Permalink to &quot;3.2 随机采样&quot;">​</a></h3><p>按候选概率随机选择 Token。高概率候选更常出现，但低概率候选仍有机会被选中。它适合需要多样创意或多个候选的任务，却会增加测试和结果验证难度。</p><h3 id="_3-3-束搜索不是通用聊天默认答案" tabindex="-1">3.3 束搜索不是通用聊天默认答案 <a class="header-anchor" href="#_3-3-束搜索不是通用聊天默认答案" aria-label="Permalink to &quot;3.3 束搜索不是通用聊天默认答案&quot;">​</a></h3><p>束搜索同时保留若干高分序列，常用于翻译等目标较集中的序列任务。开放式生成中它可能偏向普通、重复文本，并增加计算。是否使用取决于任务，不应把“搜索更宽”理解为“推理更深”。</p><h2 id="_4-temperature" tabindex="-1">4. Temperature <a class="header-anchor" href="#_4-temperature" aria-label="Permalink to &quot;4. Temperature&quot;">​</a></h2><h3 id="_4-1-temperature-缩放-logits" tabindex="-1">4.1 Temperature 缩放 logits <a class="header-anchor" href="#_4-1-temperature-缩放-logits" aria-label="Permalink to &quot;4.1 Temperature 缩放 logits&quot;">​</a></h3><p>常见处理是在 softmax 前用 temperature <code>T</code> 缩放：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(i) = softmax(zᵢ / T)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>T &lt; 1</code> 拉大相对差距，分布更尖锐。</li><li><code>T &gt; 1</code> 压小相对差距，分布更平坦。</li><li><code>T</code> 接近 0 时通常趋向最高分选择，但具体 API 对零值的定义要看文档。</li></ul><h3 id="_4-2-temperature-不提升知识" tabindex="-1">4.2 Temperature 不提升知识 <a class="header-anchor" href="#_4-2-temperature-不提升知识" aria-label="Permalink to &quot;4.2 Temperature 不提升知识&quot;">​</a></h3><p>降低 temperature 只让高分候选更占优势，不能修复错误前提；提高 temperature 增加多样性，也可能增加不连贯和结构失败。应按任务评测，而不是套用统一“最佳值”。</p><h3 id="_4-3-参数效果依赖原始分布" tabindex="-1">4.3 参数效果依赖原始分布 <a class="header-anchor" href="#_4-3-参数效果依赖原始分布" aria-label="Permalink to &quot;4.3 参数效果依赖原始分布&quot;">​</a></h3><p>若一个 Token 已远高于其他候选，改变 temperature 可能几乎不改变选择；若多个候选接近，细小变化就可能显著影响结果。相同 temperature 在不同模型和任务上不可直接比较。</p><h2 id="_5-top-p" tabindex="-1">5. Top-p <a class="header-anchor" href="#_5-top-p" aria-label="Permalink to &quot;5. Top-p&quot;">​</a></h2><h3 id="_5-1-核采样保留累计概率集合" tabindex="-1">5.1 核采样保留累计概率集合 <a class="header-anchor" href="#_5-1-核采样保留累计概率集合" aria-label="Permalink to &quot;5.1 核采样保留累计概率集合&quot;">​</a></h3><p>Top-p 先按概率从高到低排序，保留累计概率达到阈值 <code>p</code> 的最小候选集合，再在其中重新归一化采样。</p><p>例如分布为 <code>0.55, 0.25, 0.12, 0.08</code>，当 <code>p=0.8</code> 时，前两个候选累计正好达到 <code>0.8</code>，其余候选被排除。</p><h3 id="_5-2-候选数量会动态变化" tabindex="-1">5.2 候选数量会动态变化 <a class="header-anchor" href="#_5-2-候选数量会动态变化" aria-label="Permalink to &quot;5.2 候选数量会动态变化&quot;">​</a></h3><p>当分布很尖锐时，集合可能只有少数 Token；分布平坦时，需要更多 Token 才达到相同累计概率。这是 top-p 与固定保留前 <code>k</code> 个候选的 top-k 的主要差异。</p><h3 id="_5-3-不要盲目同时大幅调整多个参数" tabindex="-1">5.3 不要盲目同时大幅调整多个参数 <a class="header-anchor" href="#_5-3-不要盲目同时大幅调整多个参数" aria-label="Permalink to &quot;5.3 不要盲目同时大幅调整多个参数&quot;">​</a></h3><p>Temperature 和 top-p 都改变采样分布，叠加后难以判断质量变化来自哪里。建立基线后一次改变一个主要因素，并在固定评测集上比较。</p><h2 id="_6-停止条件" tabindex="-1">6. 停止条件 <a class="header-anchor" href="#_6-停止条件" aria-label="Permalink to &quot;6. 停止条件&quot;">​</a></h2><h3 id="_6-1-结束-token" tabindex="-1">6.1 结束 Token <a class="header-anchor" href="#_6-1-结束-token" aria-label="Permalink to &quot;6.1 结束 Token&quot;">​</a></h3><p>模型可以生成训练中表示序列结束的特殊 Token。解码器检测后停止，这通常是自然完成的主要信号之一。</p><h3 id="_6-2-输出-token-上限" tabindex="-1">6.2 输出 Token 上限 <a class="header-anchor" href="#_6-2-输出-token-上限" aria-label="Permalink to &quot;6.2 输出 Token 上限&quot;">​</a></h3><p>应用或服务设置最大输出长度，达到上限会强制停止。它是资源保护，不表示答案完成。调用方应检查完成状态，尤其不能解析被截断的 JSON 后假装成功。</p><h3 id="_6-3-停止序列" tabindex="-1">6.3 停止序列 <a class="header-anchor" href="#_6-3-停止序列" aria-label="Permalink to &quot;6.3 停止序列&quot;">​</a></h3><p>某些接口允许指定文本或 Token 序列作为停止标记。停止序列可能出现在用户数据中，也可能横跨 Token 边界；具体是否包含在返回文本中由 API 定义。</p><h3 id="_6-4-结构或工具边界" tabindex="-1">6.4 结构或工具边界 <a class="header-anchor" href="#_6-4-结构或工具边界" aria-label="Permalink to &quot;6.4 结构或工具边界&quot;">​</a></h3><p>受约束解码可以在满足 Schema 后结束，工具调用也可能产生独立完成事件。它们属于 API 和应用协议，不应与模型自然结束 Token 混为一个机制。</p><h2 id="_7-kv-cache" tabindex="-1">7. KV cache <a class="header-anchor" href="#_7-kv-cache" aria-label="Permalink to &quot;7. KV cache&quot;">​</a></h2><h3 id="_7-1-为什么需要缓存" tabindex="-1">7.1 为什么需要缓存 <a class="header-anchor" href="#_7-1-为什么需要缓存" aria-label="Permalink to &quot;7.1 为什么需要缓存&quot;">​</a></h3><p>生成第 <code>n+1</code> 个 Token 时，前 <code>n</code> 个位置的 Key 和 Value 已在之前算过。KV cache 保存每层历史位置的这些张量，新一步只需计算新位置并关注缓存。</p><h3 id="_7-2-缓存减少重复计算" tabindex="-1">7.2 缓存减少重复计算 <a class="header-anchor" href="#_7-2-缓存减少重复计算" aria-label="Permalink to &quot;7.2 缓存减少重复计算&quot;">​</a></h3><p>没有 cache，每一步都要重新处理完整前缀；有 cache，历史表示可复用。它显著改善解码速度，但不会改变模型参数或给模型增加长期记忆。</p><h3 id="_7-3-缓存占用随上下文增长" tabindex="-1">7.3 缓存占用随上下文增长 <a class="header-anchor" href="#_7-3-缓存占用随上下文增长" aria-label="Permalink to &quot;7.3 缓存占用随上下文增长&quot;">​</a></h3><p>KV cache 会随层数、序列长度、并行请求和表示尺寸占用显存。更长上下文和更多并发之间存在资源权衡。分组查询注意力、分页缓存和量化缓存等优化针对的是服务效率，不改变基本生成语义。</p><h2 id="_8-延迟与吞吐" tabindex="-1">8. 延迟与吞吐 <a class="header-anchor" href="#_8-延迟与吞吐" aria-label="Permalink to &quot;8. 延迟与吞吐&quot;">​</a></h2><h3 id="_8-1-首-token-延迟" tabindex="-1">8.1 首 Token 延迟 <a class="header-anchor" href="#_8-1-首-token-延迟" aria-label="Permalink to &quot;8.1 首 Token 延迟&quot;">​</a></h3><p>从请求到第一个输出 Token 的时间通常包括排队、网络、输入分词、预填充和首次解码。大输入会显著影响这一指标。</p><h3 id="_8-2-token-间延迟" tabindex="-1">8.2 Token 间延迟 <a class="header-anchor" href="#_8-2-token-间延迟" aria-label="Permalink to &quot;8.2 Token 间延迟&quot;">​</a></h3><p>开始输出后，每个新 Token 的生成速度决定流式体验和总完成时间。长输出即使很早看到首 Token，也可能很晚才完整结束。</p><h3 id="_8-3-吞吐与单请求延迟可能冲突" tabindex="-1">8.3 吞吐与单请求延迟可能冲突 <a class="header-anchor" href="#_8-3-吞吐与单请求延迟可能冲突" aria-label="Permalink to &quot;8.3 吞吐与单请求延迟可能冲突&quot;">​</a></h3><p>服务通过批处理提高整体 Token 吞吐，但等待凑批或资源调度可能增加单个请求延迟。应用选型应区分在线交互、批量离线处理和高并发服务。</p><h2 id="_9-随机性的真实边界" tabindex="-1">9. 随机性的真实边界 <a class="header-anchor" href="#_9-随机性的真实边界" aria-label="Permalink to &quot;9. 随机性的真实边界&quot;">​</a></h2><h3 id="_9-1-固定采样种子只能控制部分随机性" tabindex="-1">9.1 固定采样种子只能控制部分随机性 <a class="header-anchor" href="#_9-1-固定采样种子只能控制部分随机性" aria-label="Permalink to &quot;9.1 固定采样种子只能控制部分随机性&quot;">​</a></h3><p>部分系统允许设置随机种子，使同一配置更易复现。但模型版本、后端内核、并行顺序和服务实现仍可能变化。种子不是跨环境永久逐字一致承诺。</p><h3 id="_9-2-确定解码也可能有服务差异" tabindex="-1">9.2 确定解码也可能有服务差异 <a class="header-anchor" href="#_9-2-确定解码也可能有服务差异" aria-label="Permalink to &quot;9.2 确定解码也可能有服务差异&quot;">​</a></h3><p>浮点计算、同分候选、模型路由和后端更新可能造成差异。生产测试应优先断言结构、关键事实和业务结果，而非整段字符串。</p><h3 id="_9-3-多次采样可以观察分布-不会自动证明正确" tabindex="-1">9.3 多次采样可以观察分布，不会自动证明正确 <a class="header-anchor" href="#_9-3-多次采样可以观察分布-不会自动证明正确" aria-label="Permalink to &quot;9.3 多次采样可以观察分布，不会自动证明正确&quot;">​</a></h3><p>同一问题生成多个候选有助于发现不稳定和探索解法，但多数票仍可能共享同一错误。需要外部可执行检查或权威来源时，必须实际验证。</p><h2 id="_10-常见误解" tabindex="-1">10. 常见误解 <a class="header-anchor" href="#_10-常见误解" aria-label="Permalink to &quot;10. 常见误解&quot;">​</a></h2><h3 id="_10-1-temperature-越低-事实越正确" tabindex="-1">10.1 “Temperature 越低，事实越正确” <a class="header-anchor" href="#_10-1-temperature-越低-事实越正确" aria-label="Permalink to &quot;10.1 “Temperature 越低，事实越正确”&quot;">​</a></h3><p>它提高重复性和高概率候选权重，不改变参数知识或证据。</p><h3 id="_10-2-流式输出让模型生成更快" tabindex="-1">10.2 “流式输出让模型生成更快” <a class="header-anchor" href="#_10-2-流式输出让模型生成更快" aria-label="Permalink to &quot;10.2 “流式输出让模型生成更快”&quot;">​</a></h3><p>流式让用户更早看到增量结果，通常不减少模型完成全部 Token 所需的计算。</p><h3 id="_10-3-kv-cache-是模型记忆" tabindex="-1">10.3 “KV cache 是模型记忆” <a class="header-anchor" href="#_10-3-kv-cache-是模型记忆" aria-label="Permalink to &quot;10.3 “KV cache 是模型记忆”&quot;">​</a></h3><p>它是当前推理序列的计算缓存，生命周期和可见范围由推理服务管理。</p><h2 id="_11-自测" tabindex="-1">11. 自测 <a class="header-anchor" href="#_11-自测" aria-label="Permalink to &quot;11. 自测&quot;">​</a></h2><ol><li>预填充和逐 Token 解码分别处理什么？</li><li>logit、概率和实际选中 Token 是哪三个不同阶段？</li><li>Temperature 与 top-p 如何改变候选分布？</li><li>为什么达到输出上限不能被当作正常完成？</li><li>KV cache 降低了什么计算，又付出了什么资源？</li></ol><p>能够沿“输入预填充 → logits → 分布处理 → Token 选择 → cache 更新 → 停止判断”解释一次请求，就掌握了推理与采样的主过程。</p>',86)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
